examples.source:
classDiagram
  direction LR
  class Library {
    +String name
    +add(Book book) void
    +search(String query) List~Book~
  }
  class Book {
    +String isbn
    +String title
    +int year
  }
  class Author {
    +String name
  }
  class Copy {
    +int number
    +isAvailable() bool
  }
  class Lendable {
    <<interface>>
    +checkOut() void
  }
  class Member {
    +String id
    +borrow(Copy copy) Loan
  }
  class Loan {
    +Date due
    +isOverdue() bool
  }
  Library "1" *-- "*" Book : holds
  Book "*" --> "1..*" Author : written by
  Book "1" *-- "*" Copy
  Copy ..|> Lendable
  Member "1" --> "*" Loan
  Loan --> Copy
